@charset "UTF-8";
* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  background: #fff;
}

body {
  font-family: Inter, "Segoe UI", Arial, sans-serif;
  color: #231F20;
  font-size: 14px;
}

#root {
  height: calc(var(--appsmith-ui-height) * 1px);
  overflow-y: auto;
  overflow-x: hidden;
  padding: 16px 24px 20px;
}

.head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 6px;
}

.head strong {
  color: #B4232A;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.4;
}

#tila {
  font-size: 12.5px;
  font-weight: 600;
}

.ohje {
  font-size: 14px;
  color: #6B7280;
  margin: 0 0 16px;
}

.tabit {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  border-bottom: 1px solid #231F20;
}

.tab {
  border: 1px solid #E3E5E8;
  border-bottom: 0;
  background: #F3F4F6;
  border-radius: 8px 8px 0 0;
  padding: 7px 12px;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  color: #4B5563;
}

.tab.on {
  background: #231F20;
  color: #fff;
  border-color: #231F20;
}

.tab.pois {
  opacity: 0.55;
  font-style: italic;
}

.tab.plus {
  background: #fff;
  color: #B4232A;
}

.pohja {
  border: 1px solid #E3E5E8;
  border-top: 0;
  border-radius: 0 0 8px 8px;
  padding: 12px;
}

.ylä {
  display: flex;
  gap: 12px;
  align-items: flex-end;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.f {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.f label {
  font-size: 14px;
  color: #231F20;
}

input[type=text], select {
  font: inherit;
  border: 1px solid #E0DEDE;
  border-radius: 6px;
  padding: 7px 10px;
  background: #fff;
  color: #231F20;
}

input[type=checkbox] {
  accent-color: #231F20;
  width: 16px;
  height: 16px;
}

input[type=text].nimi {
  width: 320px;
  max-width: 100%;
}

.chk {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 14px;
  padding-bottom: 9px;
}

.rivi {
  display: flex;
  gap: 10px;
  align-items: center;
  border: 1px solid #E3E5E8;
  border-radius: 8px;
  padding: 7px 10px;
  margin-bottom: 6px;
  background: #FAFAFA;
}

.nro {
  flex: 0 0 22px;
  font-size: 12px;
  color: #6B7280;
  text-align: right;
}

.mn {
  flex: 1;
  min-width: 0;
}

.mn small {
  display: block;
  font-size: 11.5px;
  color: #6B7280;
}

.mn.puuttuu {
  color: #B91C1C;
}

.ic {
  border: 0;
  background: transparent;
  cursor: pointer;
  font-size: 15px;
  color: #6B7280;
  padding: 3px 6px;
  border-radius: 5px;
}

.ic:hover {
  background: #E5E7EB;
  color: #231F20;
}

.ic:disabled {
  opacity: 0.25;
  cursor: default;
  background: transparent;
}

.lisaa {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
  margin-top: 10px;
}

.lisaa select {
  min-width: 320px;
  max-width: 100%;
}

.tyhja {
  border: 2px dashed #D1D5DB;
  border-radius: 8px;
  padding: 16px;
  text-align: center;
  color: #6B7280;
}

.ala {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 14px;
}

.btn {
  border: 1px solid #FDE047;
  border-radius: 6px;
  padding: 8px 14px;
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  background: #fff;
  color: #231F20;
}

.btn:hover {
  filter: brightness(0.95);
}

.btn.pää {
  background: #FDE047;
  color: #231F20;
}

.btn:disabled {
  opacity: 0.45;
  cursor: default;
  filter: none;
}

.linkki {
  border: 0;
  background: transparent;
  color: #B4232A;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  padding: 6px 0;
}

.vihje {
  font-size: 12px;
  color: #6B7280;
}

.btn:focus-visible, input:focus-visible, select:focus-visible, .tab:focus-visible, .ic:focus-visible {
  outline: 2px solid #B4232A;
  outline-offset: 1px;
}

