        <button class="ic" title="Siirrä ylös" data-ylos="${i}" ${i===0?'disabled':''}>↑</button><button class="ic" title="Siirrä alas" data-alas="${i}" ${i===p.m.length-1?'disabled':''}>↓</button><button class="ic" title="Poista materiaali pohjasta" data-pois="${i}">✕</button></div>`; }).join('')
      :'<div class="tyhja">Pohjassa ei ole vielä materiaaleja. Lisää ne alta.</div>';
    let ed=null; const opts=D.materiaalit.filter(m=>m.akt!==false).map(m=>(m.t!==ed?(ed!==null?'</optgroup>':'')+`<optgroup label="${esc((ed=m.t)||'Muut')}">`:'')+`<option value="${m.id}">${esc(matNimi(m))}</option>`).join('')+(ed!==null?'</optgroup>':'');
    sis=`<div class="pohja"><div class="ylä"><div class="f"><label>Pohjan nimi</label><input type="text" class="nimi" id="nimi" value="${esc(p.nimi)}" placeholder="esim. Tarra (umpiliimainen)"></div>
      <label class="chk"><input type="checkbox" id="akt" ${p.akt?'checked':''}> Näytä laskurissa</label></div>
      ${rivit}
      <div class="lisaa"><select id="lisaa"><option value="">+ Lisää materiaali…</option>${opts}</select><span class="vihje">Koneet tulevat laskurissa materiaalin mukana automaattisesti. Laminointikalvo liitetään edeltävään kalvoon, joten laita se sen perään.</span></div>
      <div class="ala"><button class="linkki" data-poistapohja="1">${poistoV===p.id?'Vahvista: poista pohja "'+esc(p.nimi||'Nimetön')+'"':'Poista pohja'}</button></div></div>`;
  }
  $('#root').innerHTML=`<div class="head"><strong>Laskuripohjat</strong><span id="tila"></span></div>
    <p class="ohje">Pohja lisää laskuriin valitut materiaalit tyhjinä riveinä (Työkortti → laskuri → "+ Pohjasta…").</p>
    <div class="tabit">${tabit}</div>${sis}
    <div class="ala"><span></span><div style="display:flex;gap:8px"><button class="btn" id="peru" ${dirty&&!saving?'':'disabled'}>Peru muutokset</button><button class="btn pää" id="tallenna">Tallenna</button></div></div>`;
  asetaTila(saving?'tallennetaan':dirty?'muutoksia':'');
}
function tallenna(){
  if(saving||!dirty) return;
  if(P.some(p=>!p.nimi.trim())){ alertti('Jokaisella pohjalla pitää olla nimi.'); return; }
  const n=P.map(p=>p.nimi.trim().toLowerCase()); if(new Set(n).size!==n.length){ alertti('Kahdella pohjalla on sama nimi.'); return; }
  saving=true; asetaTila('tallennetaan');
  A.updateModel({ulos:P.map(p=>({id:p.id,nimi:p.nimi.trim(),akt:p.akt,m:p.m}))}); setTimeout(()=>A.triggerEvent('onTallenna'),150);
  setTimeout(()=>{ if(saving){ saving=false; asetaTila('virhe'); } },15000);
}
function alertti(t){ const el=$('#tila'); if(el){ el.textContent=t; el.style.color='#B91C1C'; } }
document.addEventListener('click',e=>{ const b=e.target.closest('button'); if(!b||!D) return; const d=b.dataset, p=P.find(x=>x.id===valittu);
  if(d.valitse){ valittu=d.valitse; poistoV=null; piirra(); return; }
  if(d.uusi){ const u={id:uid(),nimi:'',akt:true,m:[]}; P.push(u); valittu=u.id; muuttui(); piirra(); const ni=$('#nimi'); if(ni) ni.focus(); return; }
  if(b.id==='tallenna'){ tallenna(); return; }
  if(b.id==='peru'){ dirty=false; poistoV=null; asetaTila(''); A.triggerEvent('onLataa'); return; }
  if(!p) return;
  if(d.ylos!==undefined){ const i=+d.ylos; [p.m[i-1],p.m[i]]=[p.m[i],p.m[i-1]]; muuttui(); piirra(); }
  else if(d.alas!==undefined){ const i=+d.alas; [p.m[i+1],p.m[i]]=[p.m[i],p.m[i+1]]; muuttui(); piirra(); }
  else if(d.pois!==undefined){ p.m.splice(+d.pois,1); muuttui(); piirra(); }
  else if(d.poistapohja){ if(poistoV!==p.id){ poistoV=p.id; piirra(); return; } P=P.filter(x=>x!==p); valittu=P.length?P[0].id:null; muuttui(); piirra(); }
});
document.addEventListener('input',e=>{ const p=P.find(x=>x.id===valittu); if(!p) return;
  if(e.target.id==='nimi'){ p.nimi=e.target.value; const t=document.querySelector(`[data-valitse="${p.id}"]`); if(t) t.textContent=p.nimi||'Nimetön'; muuttui(); const b=$('#tallenna'); if(b) b.disabled=false; const pe=$('#peru'); if(pe) pe.disabled=false; } });
document.addEventListener('change',e=>{ const p=P.find(x=>x.id===valittu); if(!p) return;
  if(e.target.id==='akt'){ p.akt=e.target.checked; muuttui(); piirra(); }
  else if(e.target.id==='lisaa'&&e.target.value){ p.m.push(e.target.value); muuttui(); piirra(); const s=$('#lisaa'); if(s) s.focus(); } });
function malli(m){ if(!m) return; let d=m.d; if(typeof d==='string'){ try{ d=JSON.parse(d); }catch(e){ d=null; } }
  if(m.virhe&&m.virhe!==viimVirhe){ viimVirhe=m.virhe; if(saving){ saving=false; asetaTila('virhe'); const el=$('#tila'); if(el) el.textContent='Tallennus epäonnistui: '+String(m.virhe).split('|').slice(1).join('|').split('Where:')[0]; } }
  if(!d){ if(!D){ $('#root').innerHTML='<div class="tyhja">Ladataan…</div>'; if(!lataaPyydetty){ lataaPyydetty=true; A.triggerEvent('onLataa'); } } return; }
  if(d.haettu===haettu) return; haettu=d.haettu;
  const olisaving=saving; saving=false;
  if(dirty&&!olisaving) return; // ei ylikirjoiteta keskeneräisiä muutoksia
  lataa(d); piirra(); if(olisaving) asetaTila('tallennettu');
}
A.onReady(()=>{ malli(A.model); A.onModelChange(m=>malli(m)); });
